INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch10$PT159-S3-Q13$batch10$, 159, 3, 13, $batch10$Main Conclusion$batch10$, $batch10$Every human’s brain contains a mental representation of the external world. Yet, this representation necessarily leaves out much detail. After all, the external world is much larger and more complex than the human brain, and there is no way an object could completely represent something larger and more complex than itself.$batch10$, $batch10$Which one of the following most accurately expresses the conclusion drawn in the argument?$batch10$, $batch10$A$batch10$, true, $batch10$Batch 10; question text from local bank.$batch10$ FROM lr_sections s WHERE s.preptest=159 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT159-S3-Q13$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$A$batch10$, $batch10$The human brain’s representation of the external world leaves out much detail.$batch10$, $batch10$Correct$batch10$, true FROM lr_questions q WHERE q.qid=$batch10$PT159-S3-Q13$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$A$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$B$batch10$, $batch10$The external world is much larger and more complex than a human brain.$batch10$, $batch10$Premise$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT159-S3-Q13$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$B$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$C$batch10$, $batch10$The human brain cannot completely represent something larger and more complex than itself.$batch10$, $batch10$Premise$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT159-S3-Q13$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$C$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$D$batch10$, $batch10$The human brain contains a mental representation of the external world.$batch10$, $batch10$Background$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT159-S3-Q13$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$D$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$E$batch10$, $batch10$It is impossible for any entity to completely represent anything larger and more complicated than itself.$batch10$, $batch10$Premise$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT159-S3-Q13$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$E$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT159-S3-Q13$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Background$batch10$, $batch10$Every human brain contains a mental representation of the external world.$batch10$), (1, $batch10$Conclusion$batch10$, $batch10$This representation necessarily leaves out much detail.$batch10$), (2, $batch10$Evidence$batch10$, $batch10$The external world is much larger and more complex than the brain, and no object can completely represent something larger and more complex than itself.$batch10$), (3, $batch10$Evaluate$batch10$, $batch10$"Yet" turns to the claim, and "After all" introduces its support. Everything after "After all" supports the second sentence.$batch10$), (4, $batch10$Goal$batch10$, $batch10$The brain's representation of the world leaves out much detail.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT159-S3-Q13$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$This is the second sentence, which "After all" supports.$batch10$), ($batch10$B$batch10$, $batch10$This is the first piece of support.$batch10$), ($batch10$C$batch10$, $batch10$This applies the general rule in the last clause to the brain. It's part of the support.$batch10$), ($batch10$D$batch10$, $batch10$This is the starting fact the conclusion builds on.$batch10$), ($batch10$E$batch10$, $batch10$This is the general rule in the last clause.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT159-S3-Q13$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
